from lib import *
S = SS('k53')
F1 = [['存储类 allowVolumeExpansion', 'false'], ['patch PVC 20Mi', 'Forbidden'], ['改存储类为 true', ''], ['再 patch', '受理']]
F2 = [['patch b 为 20Mi', 'spec 变了'], ['事件', 'ExternalExpanding'], ['等外部控制器', '没人来'], ['status.capacity / PV / df', '40 秒后仍不变']]
F3 = [['改成 5Mi', '< capacity,拒绝'], ['改成 15Mi', '> capacity,受理'], ['改成 10Mi', '= capacity,拒绝']]
F4 = [['Pending 的 PVC', 'spec 不可变'], ['绑定之后', '只有 requests 能改'], ['改 accessModes', '拒绝'], ['改 requests', '受理']]
PANELS = [('f', 'flow', '扩容请求'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("存储类 k53-noexp(allowVolumeExpansion: false)的 PVC a 绑定后,把 requests.storage 从 10Mi 改成 20Mi:API Server 直接返回 Forbidden: only dynamically provisioned pvc can be resized and the storageclass that provisions the pvc must support resize,PVC 不变。把存储类的 allowVolumeExpansion 改成 true 之后,同一条 patch 立刻被受理(退出码 0)——这个字段随时可改,对已有 PVC 马上生效。", f=fl(F1, cur=[1], mark=[0], done=[3]), t=tl(S(1), mark=lidx(S(1), 'Forbidden', 'only dynamically'), done=lidx(S(1), '退出码 0')), kv=KV([['Forbidden', '准入层面的检查:类不支持扩容就不让改'], ['allowVolumeExpansion', '可以事后改,不用重建类'], ['只有动态供给的 PVC', '静态 PV 绑定的 PVC 也被拒']], ['Forbidden'])),
    step("存储类 k53-exp(允许扩容)的 PVC b 改成 20Mi,patch 成功;40 秒之后 spec.requests=20Mi,但 status.capacity 仍是 10Mi,PV capacity 仍是 10Mi,Pod 里 df 看到的大小也没变;PVC 上多出一条事件 ExternalExpanding: waiting for an external controller to expand this PVC。local-path-provisioner 不实现扩容,没有任何控制器来接这个请求。", f=fl(F2, cur=[2], mark=[3], done=[0, 1]), t=tl(S(2), mark=lidx(S(2), 'ExternalExpanding', '40 秒之后'), done=lidx(S(2), '退出码 0')), kv=KV([['spec', '你要多大(意图)'], ['status.capacity', '实际多大(结果),由扩容控制器更新'], ['ExternalExpanding', '在等 CSI external-resizer 之类的外部组件']], ['ExternalExpanding'])),
    step("b 现在 spec 是 20Mi、容量 10Mi:改成 5Mi 被拒,Forbidden: field can not be less than status.capacity;改成 15Mi(比 spec 小、比容量大)被受理,spec 变成 15Mi;再改成 10Mi(正好等于容量)仍然被拒,同样的报错,spec 停在 15Mi。", f=fl(F3, cur=[1], mark=[0, 2]), t=tl(S(3), mark=lidx(S(3), '退出码 1'), done=lidx(S(3), '15Mi(比 spec')), kv=KV([['不能缩', '低于 status.capacity 一律拒绝'], ['15Mi', '比旧的请求小、比容量大,可以'], ['10Mi', '等于容量也被拒(本文没搞清为什么)']], ['不能缩'])),
    step("还是 Pending 的 PVC c(类允许扩容)想改大到 30Mi:被拒,spec is immutable after creation except resources.requests and volumeAttributesClassName for bound claims——没绑定时 spec 整个不可变。创建 Pod 绑定之后,改 accessModes 仍然被拒(同样的报错),只改 requests.storage 为 30Mi 则受理。", f=fl(F4, cur=[1], mark=[0, 2], done=[3]), t=tl(S(4), mark=lidx(S(4), 'immutable', '退出码 1'), done=lidx(S(4), '改 requests.storage')), kv=KV([['Pending', 'spec 整个不可变,想要不同大小只能重建'], ['Bound', '只有 requests 和 volumeAttributesClassName 能改'], ['Unused 条件', '有 Pod 引用时是 False(PodUsingPVC)']], ['Bound'])),
]
A = mkartk('k53', 53, 'Kubernetes,PVC,存储扩容,allowVolumeExpansion,StorageClass,真实验证,动画演示',
    '在 kind 集群里实测 PVC 扩容的规则:存储类 allowVolumeExpansion 为 false 时改 requests.storage 被 Forbidden,事后改成 true 立刻生效;受理后 spec 变大但 status.capacity、PV 和 Pod 里的文件系统都不变,PVC 上出现 ExternalExpanding 事件,在等外部控制器;缩小不能低于 status.capacity;没绑定的 PVC spec 整个不可变,绑定后只有 requests 能改。',
    '“PVC 扩容”到底是谁在做?kubectl patch 一下 20Mi 就算扩好了吗?这篇用没有扩容能力的 local-path 存储把 API Server 管的那一半(让不让改、能改什么)和存储驱动管的那一半(真正把卷变大)拆开,看清中间停在哪一步。',
    [('Forbidden', '存储类不允许扩容时,改 PVC 大小立刻被 API Server 拒绝'), ('10Mi → 20Mi', 'spec 改了,但 40 秒后 status.capacity、PV、df 都没变'), ('ExternalExpanding', '受理之后 PVC 上的事件:在等外部控制器来扩')],
    [('先过 API Server 这一关', '<p>存储类 <code>allowVolumeExpansion: false</code> 时,把已绑定 PVC 的 <code>requests.storage</code> 从 10Mi 改成 20Mi 直接返回 <code>Forbidden: only dynamically provisioned pvc can be resized and the storageclass that provisions the pvc must support resize</code>。这是 API Server 的准入检查,与存储驱动无关。</p><p><code>allowVolumeExpansion</code> 是存储类上可以事后修改的字段,改成 <code>true</code> 后同一条 patch 立刻被受理——它对已经存在的 PVC 同样生效。</p>'),
     ('受理不等于扩好了', '<p>允许扩容的类 <code>k53-exp</code> 上,PVC b 改成 20Mi 后 patch 成功,但 40 秒之后 <code>status.capacity</code> 还是 10Mi,PV 的 capacity 还是 10Mi,Pod 里 <code>df</code> 的总大小也没变(local-path 的卷本来就是节点磁盘上的目录,<code>df</code> 看到的是整块盘)。PVC 上多出一条事件 <code>ExternalExpanding: waiting for an external controller to expand this PVC</code>。</p><p><code>spec</code> 写的是意图,<code>status.capacity</code> 是结果;从前者到后者要靠 CSI 的 external-resizer 这类控制器完成,local-path-provisioner 没有实现扩容,所以请求一直停在这里。真正的在线扩容(文件系统在容器运行时被撑大)需要支持它的 CSI 驱动,本文的集群验证不了。</p>'),
     ('只能往大改', '<p>b 的 spec 现在是 20Mi、容量 10Mi:改成 5Mi 被拒,<code>field can not be less than status.capacity</code>;改成 15Mi(比 spec 小但比容量大)被受理;改成 10Mi(正好等于容量)却仍然被拒,报错相同,spec 停在 15Mi。最后这一条是实测结果,但我没弄清为什么等于容量也算“小于”,所以不拿它下结论。</p>'),
     ('绑定前后能改什么', '<p>还是 <code>Pending</code> 的 PVC c 想把大小改成 30Mi 被拒:<code>spec is immutable after creation except resources.requests and volumeAttributesClassName for bound claims</code>——没绑定时 spec 整个不可变,想换大小只能删了重建。绑定之后,改 <code>accessModes</code> 依然被拒,只改 <code>requests.storage</code> 才被受理。</p><p>另外,v1.37 里 PVC 的 <code>status.conditions</code> 会有一条 <code>Unused</code>,有 Pod 引用时它是 <code>False</code>(reason <code>PodUsingPVC</code>)。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(Kubernetes v1.37.0),存储是 kind 自带的 local-path-provisioner,它没有扩容能力;自建的 StorageClass 与 PVC 实验后都已删除;40 秒是固定等待;“Pod 里 df”用 busybox 的 df -k 读 /d 挂载点;每种情形各一次',
     '没有验证:真正支持扩容的 CSI 驱动上的完整流程(external-resizer、ControllerExpandVolume 与 NodeExpandVolume 两个阶段、FileSystemResizePending 条件);在线扩容与需要重启 Pod 的差别;扩容失败后的恢复(RecoverVolumeExpansionFailure 特性);为什么把请求改成与容量相等会被拒;StatefulSet 的 volumeClaimTemplates 与扩容的关系'],
    '扩容', PANELS)
